content:
420    }
   421
   422    if (schunk->nvlmetalayers > 0) {
   423      for (int i = 0; i < schunk->nvlmetalayers; ++i) {
   424        if (schunk->vlmetalayers[i] != NULL) {
   425          if (schunk->vlmetalayers[i]->name != NULL)
   426            free(schunk->vlmetalayers[i]->name);
   427          if (schunk->vlmetalayers[i]->content != NULL)
   428            free(schunk->vlmetalayers[i]->content);
   429          free(schunk->vlmetalayers[i]);
   430        }
   431      }
   432    }
   433
   434    free(schunk);
   435
   436    return 0;
   437  }
