   455  /* Append an existing chunk into a super-chunk. */
   456  int blosc2_schunk_append_chunk(blosc2_schunk *schunk, uint8_t *chunk, bool copy) {
   457    int32_t chunk_nbytes;
   458    int32_t chunk_cbytes;
   459    int32_t nchunks = schunk->nchunks;
   460
   461    int rc = blosc2_cbuffer_sizes(chunk, &chunk_nbytes, &chunk_cbytes, NULL);
   462    if (rc < 0) {
   463      return rc;
   464    }
   465
   466    if (schunk->chunksize == -1) {
   467      schunk->chunksize = chunk_nbytes;  // The super-chunk is initialized now
   468    }
   469    if (chunk_nbytes > (size_t)schunk->chunksize) {
   470      BLOSC_TRACE_ERROR("Appending chunks that have different lengths in the same schunk "
   471                        "is not supported yet: %d > %d.", chunk_nbytes, schunk->chunksize);
   472      return BLOSC2_ERROR_CHUNK_APPEND;
   473    }
   474
   475    /* Update counters */
   720    // Get the length of the frame
   721    uint8_t header[FRAME_HEADER_MINLEN];
   722    uint8_t trailer[FRAME_TRAILER_MINLEN];
   723
   724    FILE* fp = NULL;
   725    bool sframe = false;
   726    struct stat path_stat;
   727
   728    if(stat(urlpath, &path_stat) < 0) {
   729      BLOSC_TRACE_ERROR("Cannot get information about the path %s.", urlpath);
   730      return NULL;
   731    }
   732    char* urlpath_cpy;
   733    if (path_stat.st_mode & S_IFDIR) {
   734      char last_char = urlpath[strlen(urlpath) - 1];
   735      if (last_char == '\\' || last_char == '/') {
   736        urlpath_cpy = malloc(strlen(urlpath));
   737        strncpy(urlpath_cpy,urlpath, strlen(urlpath) - 1);
   738        urlpath_cpy[strlen(urlpath) - 1] = '\0';
   739      }
   740      else {
   741        urlpath_cpy = malloc(strlen(urlpath) + 1);
   742        strcpy(urlpath_cpy, urlpath);
   743      }
   744      fp = sframe_open_index(urlpath_cpy, "rb");
   745      sframe = true;
   746    }
   747    else {
   748      urlpath_cpy = malloc(strlen(urlpath) + 1);
   749      strcpy(urlpath_cpy, urlpath);
   750      fp = fopen(urlpath, "rb");
   751    }
   752    size_t rbytes = fread(header, 1, FRAME_HEADER_MINLEN, fp);
   753    if (rbytes != FRAME_HEADER_MINLEN) {
   754      BLOSC_TRACE_ERROR("Cannot read from file '%s'.", urlpath);
   755      fclose(fp);
   756      free(urlpath_cpy);
   757      return NULL;
   758    }
   759    int64_t frame_len;
   760    to_big(&frame_len, header + FRAME_LEN, sizeof(frame_len));
   761
   762    blosc2_frame_s* frame = calloc(1, sizeof(blosc2_frame_s));
   763    frame->urlpath = urlpath_cpy;
   764    frame->len = frame_len;
   765    frame->sframe = sframe;
   766
   767    // Now, the trailer length
   768    fseek(fp, frame_len - FRAME_TRAILER_MINLEN, SEEK_SET);
   769    rbytes = fread(trailer, 1, FRAME_TRAILER_MINLEN, fp);
   770    fclose(fp);
   771    if (rbytes != FRAME_TRAILER_MINLEN) {
   772      BLOSC_TRACE_ERROR("Cannot read from file '%s'.", urlpath);
   773      free(urlpath_cpy);
   774      free(frame);
   775      return NULL;
   776    }
   777    int trailer_offset = FRAME_TRAILER_MINLEN - FRAME_TRAILER_LEN_OFFSET;
   778    if (trailer[trailer_offset - 1] != 0xce) {
   779      free(urlpath_cpy);
   780      free(frame);
   781      return NULL;
   782    }
   783    uint32_t trailer_len;
   784    to_big(&trailer_len, trailer + trailer_offset, sizeof(trailer_len));
   785    frame->trailer_len = trailer_len;
   786
   787    return frame;
   788  }
