   791  /* Initialize a frame out of a contiguous frame buffer */
   792  blosc2_frame_s* frame_from_cframe(uint8_t *cframe, int64_t len, bool copy) {
   793    // Get the length of the frame
   794    const uint8_t* header = cframe;
   795    int64_t frame_len;
   796    if (len < FRAME_HEADER_MINLEN) {
   797      return NULL;
   798    }
   799
   800    from_big(&frame_len, header + FRAME_LEN, sizeof(frame_len));
   801    if (frame_len != len) {   // sanity check
   802      return NULL;
   803    }
   804
   805    blosc2_frame_s* frame = calloc(1, sizeof(blosc2_frame_s));
   806    frame->len = frame_len;
   807
   808    // Now, the trailer length
   809    const uint8_t* trailer = cframe + frame_len - FRAME_TRAILER_MINLEN;
   810    int trailer_offset = FRAME_TRAILER_MINLEN - FRAME_TRAILER_LEN_OFFSET;
   811    if (trailer[trailer_offset - 1] != 0xce) {
   812      free(frame);
   813      return NULL;
   814    }
   815    uint32_t trailer_len;
   816    from_big(&trailer_len, trailer + trailer_offset, sizeof(trailer_len));
   817    frame->trailer_len = trailer_len;
   818
   819    if (copy) {
   820      frame->cframe = malloc((size_t)len);
   821      memcpy(frame->cframe, cframe, (size_t)len);
   822    }
   823    else {
   824      frame->cframe = cframe;
   825      frame->avoid_cframe_free = true;
   826    }
   827
   828    return frame;
   829  }
