   832  /* Create a frame out of a super-chunk. */
   833  int64_t frame_from_schunk(blosc2_schunk *schunk, blosc2_frame_s *frame) {
   834    int32_t nchunks = schunk->nchunks;
   835    int64_t cbytes = schunk->cbytes;
   836    int32_t chunk_cbytes;
   837    int32_t chunk_nbytes;
   838    FILE* fp = NULL;
   839    int rc;
   840
   900    to_big(h2 + FRAME_CHUNKSIZE, &chunksize, sizeof(chunksize));
   901    frame->len = h2len + cbytes + off_cbytes + FRAME_TRAILER_MINLEN;
   902    if (frame->sframe) {
   903      frame->len = h2len + off_cbytes + FRAME_TRAILER_MINLEN;
   904    }
   905    int64_t tbytes = frame->len;
   906    to_big(h2 + FRAME_LEN, &tbytes, sizeof(tbytes));
   907
   908    // Create the frame and put the header at the beginning
   909    if (frame->urlpath == NULL) {
   910      frame->cframe = malloc((size_t)frame->len);
   911      memcpy(frame->cframe, h2, h2len);
   912    }
   913    else {
   914      if (frame->sframe) {
   915        fp = sframe_open_index(frame->urlpath, "wb");
   916      }
   917      else {
   918        fp = fopen(frame->urlpath, "wb");
   919      }
   920      fwrite(h2, h2len, 1, fp);
   921    }
   922    free(h2);
   923
   924    // Fill the frame with the actual data chunks
   925    if (!frame->sframe) {
   926      coffset = 0;
   927      for (int i = 0; i < nchunks; i++) {
   928        uint8_t* data_chunk = schunk->data[i];
   929        rc = blosc2_cbuffer_sizes(data_chunk, NULL, &chunk_cbytes, NULL);
   930        if (rc < 0) {
   931          return rc;
   932        }
   933        if (frame->urlpath == NULL) {
   934          memcpy(frame->cframe + h2len + coffset, data_chunk, (size_t)chunk_cbytes);
   935        } else {
   936          fwrite(data_chunk, (size_t)chunk_cbytes, 1, fp);
   937        }
   938        coffset += chunk_cbytes;
   939      }
   940      if ((int64_t)coffset != cbytes) {
   941        return BLOSC2_ERROR_FAILURE;
   942      }
   943    }
   944
   945    // Copy the offsets chunk at the end of the frame
   946    if (frame->urlpath == NULL) {
   947      memcpy(frame->cframe + h2len + cbytes, off_chunk, off_cbytes);
   948    }
   949    else {
   950      fwrite(off_chunk, (size_t)off_cbytes, 1, fp);
   951      fclose(fp);
   952    }
   953    free(off_chunk);
   954    rc = frame_update_trailer(frame, schunk);
   955    if (rc < 0) {
   956      return rc;
   957    }
   958
   959    return frame->len;
   960  }
