   963  // Get the compressed data offsets
   964  uint8_t* get_coffsets(blosc2_frame_s *frame, int32_t header_len, int64_t cbytes, int32_t *off_cbytes) {
   965    int32_t chunk_cbytes;
   966    int rc;
   967
   968    if (frame->coffsets != NULL) {
   969      if (off_cbytes != NULL) {
   970        rc = blosc2_cbuffer_sizes(frame->coffsets, NULL, &chunk_cbytes, NULL);
   971        if (rc < 0) {
   972          return NULL;
   973        }
   974        *off_cbytes = (int32_t)chunk_cbytes;
   975      }
   976      return frame->coffsets;
   977    }
   978    if (frame->cframe != NULL) {
   979      int64_t off_pos = header_len;
   980      if (cbytes < INT64_MAX - header_len) {
   981        off_pos += cbytes;
   982      }
   983      // Check that there is enough room to read Blosc header
   984      if (off_pos < 0 || off_pos > INT64_MAX - BLOSC_EXTENDED_HEADER_LENGTH ||
   985          off_pos + BLOSC_EXTENDED_HEADER_LENGTH > frame->len) {
   986        BLOSC_TRACE_ERROR("Cannot read the offsets outside of frame boundary.");
   987        return NULL;
   988      }
   989      // For in-memory frames, the coffset is just one pointer away
   990      uint8_t* off_start = frame->cframe + off_pos;
   991      if (off_cbytes != NULL) {
   992        rc = blosc2_cbuffer_sizes(off_start, NULL, &chunk_cbytes, NULL);
   993        if (rc < 0) {
   994          return NULL;
   995        }
   996        *off_cbytes = (int32_t)chunk_cbytes;
   997        if (*off_cbytes < 0 || off_pos + *off_cbytes > frame->len) {
   998          BLOSC_TRACE_ERROR("Cannot read the cbytes outside of frame boundary.");
   999          return NULL;
  1000        }
  1001      }
  1002      return off_start;
  1003    }
  1004
  1005    int64_t trailer_offset = get_trailer_offset(frame, header_len, true);
  1006
  1007    if (trailer_offset < BLOSC_EXTENDED_HEADER_LENGTH || trailer_offset + FRAME_TRAILER_MINLEN > frame->len) {
  1008      BLOSC_TRACE_ERROR("Cannot read the trailer out of the frame.");
  1009      return NULL;
  1010    }
  1011
  1012    int32_t coffsets_cbytes;
  1013    if (frame->sframe) {
  1014      coffsets_cbytes = (int32_t)(trailer_offset - (header_len + 0));
  1015    }
  1016    else {
  1017      coffsets_cbytes = (int32_t)(trailer_offset - (header_len + cbytes));
  1018    }
  1019
  1020    if (off_cbytes != NULL) {
  1021      *off_cbytes = coffsets_cbytes;
  1022    }
  1023
  1024    FILE* fp = NULL;
  1025    uint8_t* coffsets = malloc((size_t)coffsets_cbytes);
  1026    if (frame->sframe) {
  1027      fp = sframe_open_index(frame->urlpath, "rb");
  1028      fseek(fp, header_len + 0, SEEK_SET);
  1029    }
  1030    else {
  1031      fp = fopen(frame->urlpath, "rb");
  1032      fseek(fp, header_len + cbytes, SEEK_SET);
  1033    }
  1034    size_t rbytes = fread(coffsets, 1, (size_t)coffsets_cbytes, fp);
  1035    fclose(fp);
  1036    if (rbytes != (size_t)coffsets_cbytes) {
  1037      BLOSC_TRACE_ERROR("Cannot read the offsets out of the frame.");
  1038      free(coffsets);
  1039      return NULL;
  1040    }
